insert into public.sessions (id, date, title, summary, hooks, loot_xp) values ('45bd4753-0ee7-4fbf-a370-180b0f2e0ee3', $gd_str$2026-07-31$gd_str$::date, $gd_str$Sessão 2$gd_str$, $gd_str$Introducao de pedro e cassol; mistérios da maldiçao de Nekkan Adonai; conheceram Amadeus e Barcus; Hughes de Pareaud e A Catedral; A cerimonia aberta. $gd_str$, $gd_str$$gd_str$, $gd_str$$gd_str$);
insert into public.sessions (id, date, title, summary, hooks, loot_xp) values ('6c23b2df-e882-4972-88e8-ccbc39bf58c4', $gd_str$2026-07-24$gd_str$::date, $gd_str$Sessão 1$gd_str$, $gd_str$Introduçao do mundo; criacao de fichas; conexoes prévias; inicio da campanha com erich, ronny e mako; carta a Lucian sobre a trama da morte do Grao Mestre; chegada a Payen para o funderal de Guilherme; descoberta do caixao de Demian; visao e contato com a maldiçao de Nekkan Adonai; visao de um demonio.$gd_str$, $gd_str$$gd_str$, $gd_str$$gd_str$);
insert into public.threads (id, city_id, title, status, description, updated_at) values ('67b9a3f1-c9bf-4786-8211-f769f6c5f0cc', NULL, $gd_str$A Maldição de Demian, o Louco$gd_str$, $gd_str$ativo$gd_str$, $gd_str$Principal fio narrativo, explora a mensagem deixada por Demian em seu corpo, sobre a maldição de Nekkan Adonai, com os dizeres "Ele não é legítimo"$gd_str$, $gd_str$2026-08-02T01:13:06.660Z$gd_str$::timestamptz);
insert into public.threads (id, city_id, title, status, description, updated_at) values ('7176ea41-9b45-47f2-9798-0d6fc943d3f7', 'a987ff25-4cd3-44a5-afe0-db1a9e612b73', $gd_str$A Morte de Guillaume de Harcourt $gd_str$, $gd_str$ativo$gd_str$, $gd_str$Guillaume/Guilherme, amigo pessoal de todos do grupo, morreu de "causas naturais" - mesmo sendo saudável e templário - na cidade e Montbard. $gd_str$, $gd_str$2026-08-02T01:14:24.836Z$gd_str$::timestamptz);
insert into public.threads (id, city_id, title, status, description, updated_at) values ('ed678a99-d84f-4e49-9a2d-162ad9f8c7a5', NULL, $gd_str$O Boi de Piranha$gd_str$, $gd_str$ativo$gd_str$, $gd_str$Guilherme, antes de morrer, deixou uma mensagem criptografada em um livro dedicado ao Lucian, informando que o atual grão mestre, Hughes de Payen, se voluntariou a ser alvo de uma emboscada e logo morrerá, em algum ataque sem precedentes frente aos Templários.$gd_str$, $gd_str$2026-08-02T01:15:52.338Z$gd_str$::timestamptz);
